-- -------------------------------------------------------------------------
-- Cataclysm high-end: the 62 items that had no item_template row, plus 114 display ids
-- -------------------------------------------------------------------------
-- Closes the last two gaps in the catalogue.
--
-- 1. 62 items existed in neither item_template NOR the client Item.dbc. They are
--    inserted in full here; 05_cata_highend_import.sql could not touch them because
--    it is UPDATE-only, which is a silent no-op for a row that does not exist.
--    Item.dbc and ItemDisplayInfo.dbc have already been rebuilt and deployed with
--    rows for them, so the server will not complain about class/slot/display.
--
-- 2. 114 items had a row but displayid 0, i.e. no model or icon at all. Each now
--    points at a freshly minted ItemDisplayInfo row (ids 800000+) carrying the icon
--    -- and where the slot has geometry, the model and texture -- that Blizzard
--    shipped for that exact item, read from the Cata client display chain
--    (Item.db2 -> ItemDisplayInfo.dbc). The server force-corrects displayid from
--    Item.dbc, so without this the DB would disagree with what it actually loads.
--
-- Stats, armour, weapon damage, durability and the field validation are identical
-- to 05 -- same generator, same curves, same sanitiser.
-- Corrections applied by the validator: ItemLimitCategory 10, RequiredReputationFaction 5
--
-- Order-independent with respect to 09: the inserted rows carry the required level
-- from the SAME ilvl ladder 09 applies, baked into the INSERT. 09 is UPDATE-only and
-- would silently skip these 62 if it ran first, which is exactly why it is baked in.
-- Idempotent: DELETE then INSERT for the new rows, plain UPDATE for the rest.
-- -------------------------------------------------------------------------

DELETE FROM `item_template` WHERE `entry` IN (
  56467, 64693, 64743, 64818, 64823, 64849, 65010, 65104, 65274, 65360, 68172, 68173,
  68174, 68175, 68176, 69766, 69767, 69768, 69769, 69770, 71327, 71328, 71329, 71330,
  71333, 71334, 71335, 71336, 71337, 71338, 71388, 71389, 71390, 71391, 71392, 71571,
  71633, 78004, 78005, 78006, 78007, 78008, 78506, 78507, 78508, 78509, 78510, 78520,
  78521, 78522, 78523, 78524, 78543, 78544, 78545, 78546, 78547, 78585, 78586, 78587,
  78588, 78589);

